  'money.invoices': H('money', 'All invoices', 'Shows every invoice you have made, newest first.', '', 'A list of all invoices with their status and total.'),
  'card.phone': H('card', 'Phone number', 'Calls this customer from your phone.', '', 'Tap the number to ring them.'),
  'card.email': H('card', 'Email address', 'Starts an email to this customer.', '', 'Tap it to write to them from your email app.'),
  'card.social': H('card', 'Social media link', 'Opens the social media page they gave on the form.', '', 'A quick way to check who they are.'),
  'hold.longer': H('holds', 'Reserve their games longer', 'Gives them more time to pay: opens a small box with how long the games are held now, the number of more days (3 to start) and Save.', '', 'As you type the days it shows the new date. Save, and the card says Games reserved until <the new date>. You can do it again any time.'),
  'hold.days': H('holds', 'More days', 'How many more days to reserve their games. It starts at 3; type another number if you like.', '', 'Counted from the current end date (or from now, if it already ended or was reserved by hand with no end date). The New date line follows what you type.'),
